import re
base = 'C:/xampp/htdocs/MAICC-IFRS9/tools/compliance/standards/'


def patch(fn, pairs):
    p = base + fn
    s = open(p, encoding='utf-8').read()
    for old, new in pairs:
        assert s.count(old) == 1, (fn, old[:90], s.count(old))
        s = s.replace(old, new)
    open(p, 'w', encoding='utf-8', newline='\n').write(s)
    print('ok', fn)


